# SIREN patch - pdf stage 0: embedded Noto Sans / DejaVu symbol subsets for every PDF text page.
# Takes the target html path as argv[1]; applies cleanly to pending/FROZEN_1_62_0.html and is
# idempotent (refuses to apply twice). Regions: new block before `class PdfBuilder {`;
# buildReportPdf (fonts + text operators); pdfEscapeText removed (its only callers are gone).
import io, os, sys
APP = sys.argv[1]
s = io.open(APP, encoding='utf-8', newline='').read(); orig = s
def rep(anchor, new, n=1):
    global s; c = s.count(anchor); assert c == n, (c, anchor[:90]); s = s.replace(anchor, new)
if 'const PDF_FONT_FILES = {' in s:
    print('pdf_fonts already applied'); sys.exit(0)

STAGE0_BLOCK = r"""      /* ---- PDF text fonts ----------------------------------------------------
         The base-14 Helvetica the PDF writer used to name only knows WinAnsi, so
         every ș ț ă (and any letter outside Latin-1) printed as '?'. The writer now
         embeds a subset of Noto Sans (regular + bold: Latin, Latin Extended-A/B,
         general punctuation) and a small DejaVu Sans subset for arrows, ticks and
         shapes. Text is written as glyph ids (Identity-H) with a ToUnicode map, so
         it stays selectable and searchable. If the font data cannot be read, the
         same encoder falls back to Helvetica and WinAnsi codes - the report still
         exports, only the rare letters turn into '?'.  The font files are subset at
         build time (pending/impl-pdf/fonts/subset.py); do not edit the data. */
      const PDF_FONT_FILES = {
        regular: { name: 'NotoSans-Regular', flags: 32, bbox: [-518, -242, 1498, 1059], ascent: 1069, descent: -293, capHeight: 714, stemV: 80, base14: 'Helvetica', data: '' },
        bold: { name: 'NotoSans-Bold', flags: 32, bbox: [-570, -244, 1638, 1050], ascent: 1069, descent: -293, capHeight: 714, stemV: 130, base14: 'Helvetica-Bold', data: '' },
        symbols: { name: 'DejaVuSans-Symbols', flags: 4, bbox: [-3, -271, 1385, 1017], ascent: 928, descent: -236, capHeight: 349, stemV: 80, base14: 'Helvetica', data: '' }
      };
      const pdfFontCache = new Map();

      // Reads the three tables the PDF needs from a TrueType file: advance widths
      // (hmtx), the character map (cmap format 4) and the em size (head).
      function pdfFontParse(bytes) {
        const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
        const numTables = view.getUint16(4);
        const tables = {};
        for (let i = 0; i < numTables; i += 1) {
          const at = 12 + i * 16;
          const tag = String.fromCharCode(view.getUint8(at), view.getUint8(at + 1), view.getUint8(at + 2), view.getUint8(at + 3));
          tables[tag] = { offset: view.getUint32(at + 8), length: view.getUint32(at + 12) };
        }
        if (!tables.head || !tables.hhea || !tables.hmtx || !tables.cmap || !tables.maxp) throw new Error('font tables missing');
        const unitsPerEm = view.getUint16(tables.head.offset + 18) || 1000;
        const numGlyphs = view.getUint16(tables.maxp.offset + 4);
        const metricCount = view.getUint16(tables.hhea.offset + 34);
        const widths = new Uint16Array(numGlyphs);
        let lastWidth = 0;
        for (let gid = 0; gid < numGlyphs; gid += 1) {
          if (gid < metricCount) lastWidth = view.getUint16(tables.hmtx.offset + gid * 4);
          widths[gid] = lastWidth;
        }
        const cmapAt = tables.cmap.offset;
        const subtables = view.getUint16(cmapAt + 2);
        let sub = 0;
        for (let i = 0; i < subtables; i += 1) {
          const platform = view.getUint16(cmapAt + 4 + i * 8);
          const encoding = view.getUint16(cmapAt + 6 + i * 8);
          const offset = view.getUint32(cmapAt + 8 + i * 8);
          if (view.getUint16(cmapAt + offset) !== 4) continue;
          if (platform === 3 && encoding === 1) { sub = cmapAt + offset; break; }
          if (platform === 0 && !sub) sub = cmapAt + offset;
        }
        if (!sub) throw new Error('no cmap format 4');
        const segX2 = view.getUint16(sub + 6);
        const cmap = new Map();
        for (let i = 0; i < segX2 / 2; i += 1) {
          const end = view.getUint16(sub + 14 + i * 2);
          const start = view.getUint16(sub + 16 + segX2 + i * 2);
          const delta = view.getInt16(sub + 16 + segX2 * 2 + i * 2);
          const rangeAt = sub + 16 + segX2 * 3 + i * 2;
          const rangeOffset = view.getUint16(rangeAt);
          if (start === 0xFFFF) continue;
          for (let code = start; code <= end; code += 1) {
            let gid;
            if (rangeOffset === 0) gid = (code + delta) & 0xFFFF;
            else {
              const glyphAt = rangeAt + rangeOffset + (code - start) * 2;
              if (glyphAt + 1 >= bytes.byteLength) continue;
              gid = view.getUint16(glyphAt);
              if (gid) gid = (gid + delta) & 0xFFFF;
            }
            if (gid) cmap.set(code, gid);
          }
        }
        return { bytes, unitsPerEm, numGlyphs, widths, cmap };
      }

      // The parsed font for a key ('regular' | 'bold' | 'symbols'), or null when
      // the data could not be read - decided once per session.
      function pdfFont(key) {
        if (pdfFontCache.has(key)) return pdfFontCache.get(key);
        let font = null;
        try {
          const spec = PDF_FONT_FILES[key];
          const bin = atob(spec.data);
          const bytes = new Uint8Array(bin.length);
          for (let i = 0; i < bin.length; i += 1) bytes[i] = bin.charCodeAt(i);
          font = Object.assign(pdfFontParse(bytes), { key, spec });
        } catch (error) {
          console.error('PDF font could not be loaded; Helvetica is used instead', key, error);
          font = null;
        }
        pdfFontCache.set(key, font);
        return font;
      }

      // WinAnsi code for the Helvetica fallback only (the embedded fonts do not need it).
      const PDF_WINANSI = { 0x20AC: 128, 0x201A: 130, 0x0192: 131, 0x201E: 132, 0x2026: 133, 0x2020: 134, 0x2021: 135, 0x02C6: 136, 0x2030: 137, 0x0160: 138, 0x2039: 139, 0x0152: 140, 0x017D: 142, 0x2018: 145, 0x2019: 146, 0x201C: 147, 0x201D: 148, 0x2022: 149, 0x2013: 150, 0x2014: 151, 0x02DC: 152, 0x2122: 153, 0x0161: 154, 0x203A: 155, 0x0153: 156, 0x017E: 158, 0x0178: 159 };
      let pdfFallbackMeasure = null;
      function pdfBase14Width(text, bold) {
        if (!pdfFallbackMeasure) pdfFallbackMeasure = document.createElement('canvas').getContext('2d');
        if (!pdfFallbackMeasure) return text.length * 0.5;
        // Arial is metric-compatible with Helvetica, so a canvas can measure it.
        pdfFallbackMeasure.font = `${bold ? '700' : '400'} 100px Arial, Helvetica, sans-serif`;
        return pdfFallbackMeasure.measureText(text).width / 100;
      }

      /* THE one encoder for every piece of PDF text. Returns the runs to write
         (font key + hex glyph string per run - a symbol may need the symbol font in
         the middle of a line), the advance width in em (multiply by the size) and
         how many characters had no glyph anywhere and were written as '?'. */
      function pdfEncodeText(text, bold) {
        const primaryKey = bold ? 'bold' : 'regular';
        const primary = pdfFont(primaryKey);
        const runs = [];
        let width = 0;
        let lost = 0;
        const value = String(text == null ? '' : text).replace(/[\t\n\r\f\v]/g, ' ');
        if (!primary) {
          let hex = '';
          for (const ch of value) {
            const code = ch.codePointAt(0);
            let byte = -1;
            if (code < 0x7F) byte = code;
            else if (code >= 0xA0 && code <= 0xFF) byte = code;
            else if (PDF_WINANSI[code] !== undefined) byte = PDF_WINANSI[code];
            else if (code >= 0x2000 && code <= 0x200B) byte = 32;
            if (byte < 0) { lost += 1; byte = 63; }
            hex += (byte < 16 ? '0' : '') + byte.toString(16);
          }
          runs.push({ font: primaryKey, hex });
          return { runs, width: pdfBase14Width(value, bold), lost };
        }
        let current = null;
        const push = (fontKey, font, gid) => {
          if (!current || current.font !== fontKey) { current = { font: fontKey, hex: '' }; runs.push(current); }
          current.hex += gid.toString(16).padStart(4, '0');
          width += font.widths[gid] / font.unitsPerEm;
        };
        for (const ch of value) {
          let code = ch.codePointAt(0);
          if (code >= 0x2000 && code <= 0x200B && !primary.cmap.has(code)) code = 32;
          if (primary.cmap.has(code)) { push(primaryKey, primary, primary.cmap.get(code)); continue; }
          const symbols = pdfFont('symbols');
          if (symbols && symbols.cmap.has(code)) { push('symbols', symbols, symbols.cmap.get(code)); continue; }
          // Invisible joiners and variation selectors simply vanish; anything else becomes '?'.
          if (code === 0x200D || code === 0xFE0E || code === 0xFE0F || code === 0xFEFF || code === 0x00AD) continue;
          lost += 1;
          push(primaryKey, primary, primary.cmap.get(63));
        }
        return { runs, width, lost };
      }

      function pdfTextWidth(text, size, bold) { return pdfEncodeText(text, bold).width * size; }

      // The Tf/Tj pairs that draw one encoded line; the caller opens BT, positions and closes ET.
      function pdfTextShowOps(encoded, size, fonts) {
        return encoded.runs.map(run => `/${fonts.use(run.font)} ${formatPdfNumber(size)} Tf <${run.hex}> Tj`).join(' ');
      }

      /* The font objects of one PDF document, written the first time each font is
         used. use(key) -> the resource name (F1 regular, F2 bold, F3 symbols);
         dict() -> the body of the page's /Font dictionary. */
      function pdfFontResources(pdf) {
        const names = { regular: 'F1', bold: 'F2', symbols: 'F3' };
        const ids = {};
        return {
          use(key) {
            if (!names[key]) key = 'regular';
            if (!ids[key]) ids[key] = pdfEmbedFont(pdf, key);
            return names[key];
          },
          dict() { return Object.keys(ids).map(key => `/${names[key]} ${ids[key]} 0 R`).join(' '); }
        };
      }

      // Type0 + CIDFontType2 + descriptor + the TrueType bytes + ToUnicode, or the
      // base-14 stand-in when the embedded font is not available.
      function pdfEmbedFont(pdf, key) {
        const font = pdfFont(key);
        const spec = PDF_FONT_FILES[key];
        if (!font) return pdf.add(`<< /Type /Font /Subtype /Type1 /BaseFont /${spec.base14} /Encoding /WinAnsiEncoding >>`);
        const name = `SIRENA+${spec.name}`;
        const fileId = pdf.addStream(`/Length1 ${font.bytes.length}`, font.bytes);
        const descriptorId = pdf.add(`<< /Type /FontDescriptor /FontName /${name} /Flags ${spec.flags} /FontBBox [${spec.bbox.join(' ')}] /ItalicAngle 0 /Ascent ${spec.ascent} /Descent ${spec.descent} /CapHeight ${spec.capHeight} /StemV ${spec.stemV} /FontFile2 ${fileId} 0 R >>`);
        const scale = 1000 / font.unitsPerEm;
        const widths = Array.from(font.widths, w => Math.round(w * scale)).join(' ');
        const cidId = pdf.add(`<< /Type /Font /Subtype /CIDFontType2 /BaseFont /${name} /CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >> /FontDescriptor ${descriptorId} 0 R /DW 1000 /W [0 [${widths}]] /CIDToGIDMap /Identity >>`);
        const toUnicodeId = pdf.addStream('', new TextEncoder().encode(pdfToUnicodeCMap(font)));
        return pdf.add(`<< /Type /Font /Subtype /Type0 /BaseFont /${name} /Encoding /Identity-H /DescendantFonts [${cidId} 0 R] /ToUnicode ${toUnicodeId} 0 R >>`);
      }

      // glyph id -> code point, so copy/paste and search read real letters.
      function pdfToUnicodeCMap(font) {
        const byGid = new Map();
        font.cmap.forEach((gid, code) => { if (!byGid.has(gid) || byGid.get(gid) > code) byGid.set(gid, code); });
        const pairs = Array.from(byGid.entries()).sort((a, b) => a[0] - b[0]);
        const ranges = [];
        pairs.forEach(([gid, code]) => {
          const last = ranges[ranges.length - 1];
          if (last && gid === last.end + 1 && code === last.code + (last.end - last.start) + 1 && (gid >> 8) === (last.start >> 8)) last.end = gid;
          else ranges.push({ start: gid, end: gid, code });
        });
        const hex4 = n => n.toString(16).padStart(4, '0');
        const lines = ['/CIDInit /ProcSet findresource begin', '12 dict begin', 'begincmap', '/CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def', '/CMapName /Adobe-Identity-UCS def', '/CMapType 2 def', '1 begincodespacerange', '<0000> <ffff>', 'endcodespacerange'];
        for (let i = 0; i < ranges.length; i += 100) {
          const chunk = ranges.slice(i, i + 100);
          lines.push(`${chunk.length} beginbfrange`);
          chunk.forEach(r => lines.push(`<${hex4(r.start)}> <${hex4(r.end)}> <${hex4(r.code)}>`));
          lines.push('endbfrange');
        }
        lines.push('endcmap', 'CMapName currentdict /CMap defineresource pop', 'end', 'end');
        return lines.join('\n');
      }

"""

# 1. the font data, parser, encoder and embedder sit right before the PDF writer
rep("      class PdfBuilder {", STAGE0_BLOCK + "      class PdfBuilder {")

# 2. the report PDF: real fonts instead of base-14 Helvetica, text through the one encoder
rep(r"""      // Text pages use the PDF base-14 Helvetica, so the report stays selectable and searchable.
      function buildReportPdf(pages, pageWidth, pageHeight, margin) {
        const pdf = new PdfBuilder();
        const catalogId = pdf.reserve();
        const pagesId = pdf.reserve();
        const fontId = pdf.add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
        const boldId = pdf.add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
        const pageIds = [];
""", r"""      // Text pages use the embedded Noto Sans (pdfFontResources), so the report stays
      // selectable and searchable and Romanian letters print as themselves.
      function buildReportPdf(pages, pageWidth, pageHeight, margin) {
        const pdf = new PdfBuilder();
        const catalogId = pdf.reserve();
        const pagesId = pdf.reserve();
        const fonts = pdfFontResources(pdf);
        const pageIds = [];
""")
rep(r"""            const caption = pdfEscapeText(page.caption || '');
            const content = `BT /F2 11 Tf ${formatPdfNumber(margin)} ${formatPdfNumber(pageHeight - margin - 6)} Td (${caption}) Tj ET\n`""",
    r"""            const caption = pdfTextShowOps(pdfEncodeText(page.caption || '', true), 11, fonts);
            const content = `BT ${formatPdfNumber(margin)} ${formatPdfNumber(pageHeight - margin - 6)} Td ${caption} ET\n`""")
rep(r"""            resources = `<< /ProcSet [/PDF /Text /ImageC] /Font << /F1 ${fontId} 0 R /F2 ${boldId} 0 R >> /XObject << /Im0 ${imageId} 0 R >> >>`;""",
    r"""            resources = `<< /ProcSet [/PDF /Text /ImageC] /Font << ${fonts.dict()} >> /XObject << /Im0 ${imageId} 0 R >> >>`;""")
rep(r"""              parts.push(`BT /${bold ? 'F2' : 'F1'} ${size} Tf ${formatPdfNumber(margin)} ${formatPdfNumber(y)} Td (${pdfEscapeText(line)}) Tj ET`);""",
    r"""              parts.push(`BT ${formatPdfNumber(margin)} ${formatPdfNumber(y)} Td ${pdfTextShowOps(pdfEncodeText(line, bold), size, fonts)} ET`);""")
rep(r"""            resources = `<< /ProcSet [/PDF /Text] /Font << /F1 ${fontId} 0 R /F2 ${boldId} 0 R >> >>`;""",
    r"""            resources = `<< /ProcSet [/PDF /Text] /Font << ${fonts.dict()} >> >>`;""")

# 3. pdfEscapeText wrote '?' for everything outside Latin-1; nothing calls it any more
rep(r"""      function pdfEscapeText(value) {
        // WinAnsi: drop anything outside Latin-1 so the text operator stays valid.
        return String(value || '')
          .replace(/[\\()]/g, ch => '\\' + ch)
          .replace(/[^\x20-\x7E\xA0-\xFF]/g, '?');
      }

""", "")
assert 'pdfEscapeText' not in s, 'a caller of pdfEscapeText remains'

tmp = APP + '.tmp'; io.open(tmp, 'w', encoding='utf-8', newline='').write(s); os.replace(tmp, APP)
print('applied pdf_fonts', len(orig), '->', len(s), 'delta', len(s) - len(orig))
